"""Fix *_qmltyperegistrations.cpp generated by the Qt 6.7 registrar.

Qt 6.7's QMetaType::fromType<T>() does not accept a Q_NAMESPACE, yet the
registrar emits such a line before every qmlRegisterNamespaceAndRevisions
call. That call is the real registration, so the fromType line is dropped.

Usage: python qmltypes_fix.py <build-dir>     (idempotent; run after generation)
"""
import re
import sys
from pathlib import Path

build = Path(sys.argv[1])
rx = re.compile(r"^\s*QMetaType::fromType<([^>]+)>\(\)\.id\(\);\s*$")
n = 0
for path in build.rglob("*_qmltyperegistrations.cpp"):
    lines = path.read_text(encoding="utf-8").split("\n")
    out = []
    for i, line in enumerate(lines):
        m = rx.match(line)
        nxt = lines[i + 1] if i + 1 < len(lines) else ""
        if m and "qmlRegisterNamespaceAndRevisions" in nxt and m.group(1) in nxt:
            continue
        out.append(line)
    if len(out) != len(lines):
        path.write_text("\n".join(out), encoding="utf-8", newline="\n")
        n += 1
        print("  fixed", path.name)
print(f"qmltypes fixed: {n}")
